"""Minimal stdio MCP client for `atira mcp`: mcp.py list | mcp.py call <tool> '<json args>'."""
import json, os, subprocess, sys

env = dict(os.environ, PATH=os.path.expanduser("~/.local/bin") + ":" + os.environ["PATH"])
p = subprocess.Popen(["atira", "mcp"], stdin=subprocess.PIPE, stdout=subprocess.PIPE, env=env, text=True)
n = 0


def rpc(method, params=None, notify=False):
    global n
    msg = {"jsonrpc": "2.0", "method": method}
    if params is not None:
        msg["params"] = params
    if not notify:
        n += 1
        msg["id"] = n
    p.stdin.write(json.dumps(msg) + "\n")
    p.stdin.flush()
    if notify:
        return None
    while True:
        line = p.stdout.readline()
        if not line:
            raise SystemExit("closed")
        d = json.loads(line)
        if d.get("id") == n:
            return d


rpc("initialize", {"protocolVersion": "2024-11-05", "capabilities": {}, "clientInfo": {"name": "x", "version": "1"}})
rpc("notifications/initialized", notify=True)
if sys.argv[1] == "list":
    for t in rpc("tools/list")["result"]["tools"]:
        print(t["name"], json.dumps(t.get("inputSchema", {}).get("properties", {}))[:600])
        print("   ", t.get("description", "")[:400])
else:
    r = rpc("tools/call", {"name": sys.argv[2], "arguments": json.loads(sys.argv[3])})
    for c in r.get("result", {}).get("content", []):
        print(c.get("text", c))
    if "error" in r:
        print(r["error"])
p.terminate()

